import React, { useState, useEffect, useRef } from 'react';
import { INSTRUMENTS } from '../constants';
import { Instrument, AccountSettings } from '../types';
import { DollarSign, Percent, ArrowUpCircle, ArrowDownCircle, Crosshair, Lock, Target, Square, CheckSquare, ChevronDown } from 'lucide-react';

interface CalculatorProps {
  settings: AccountSettings;
}

type CalcMode = 'FIXED_RISK' | 'FIXED_LOTS';

const Calculator: React.FC<CalculatorProps> = ({ settings }) => {
  // --- STATE ---
  const [instrument, setInstrument] = useState<Instrument>(INSTRUMENTS[0]);
  const [direction, setDirection] = useState<'BUY' | 'SELL'>('SELL');

  // Calculation Mode
  const [calcMode, setCalcMode] = useState<CalcMode>('FIXED_RISK');

  // Core Inputs
  const [balance, setBalance] = useState<number>(settings.balance);
  const [lotSize, setLotSize] = useState<number>(0);
  const [riskAmount, setRiskAmount] = useState<number>(0);
  const [riskPercent, setRiskPercent] = useState<number>(1);

  // Price Inputs
  const [entryPrice, setEntryPrice] = useState<number>(0);

  // Stop Loss
  const [slEnabled, setSlEnabled] = useState(true);
  const [slPrice, setSlPrice] = useState<number>(0);
  const [slDistance, setSlDistance] = useState<number>(0);

  // Take Profit
  const [tpEnabled, setTpEnabled] = useState(true);
  const [tpPrice, setTpPrice] = useState<number>(0);
  const [tpDistance, setTpDistance] = useState<number>(0);

  // Outputs
  const [rewardAmount, setRewardAmount] = useState<number>(0);
  const [rrRatio, setRrRatio] = useState<number>(0);

  // Helpers
  const isIndex = instrument.type === 'INDEX';
  const unitLabel = isIndex ? 'Pts' : 'Pips';
  const pricePrecision = instrument.pipSize >= 0.01 ? 2 : instrument.symbol === 'USDMXN' ? 4 : 5;

  // --- INITIALIZATION ---
  useEffect(() => {
    // Set realistic default entry prices based on current markets
    const sym = instrument.symbol;
    if (sym === 'EURUSD') setEntryPrice(1.0500);
    else if (sym === 'GBPUSD') setEntryPrice(1.2600);
    else if (sym === 'USDJPY') setEntryPrice(152.00);
    else if (sym === 'USDCHF') setEntryPrice(0.8800);
    else if (sym === 'EURJPY') setEntryPrice(160.00);
    else if (sym === 'EURGBP') setEntryPrice(0.8300);
    else if (sym === 'GBPCHF') setEntryPrice(1.1100);
    else if (sym === 'USDMXN') setEntryPrice(20.3500);

    else if (sym === 'NAS100') setEntryPrice(20800);
    else if (sym === 'SPX500') setEntryPrice(5900);
    else if (sym === 'US30') setEntryPrice(43500);
    else if (sym === 'UK100') setEntryPrice(8300);
    else if (sym === 'FRA40') setEntryPrice(7400);
    else if (sym === 'JP225') setEntryPrice(39000); // Standard Nikkei level

    else if (sym === 'XAUUSD') setEntryPrice(2650);
    else if (sym === 'BTCUSD') setEntryPrice(95000);
    else setEntryPrice(0);

    // Set default SL distance based on volatility
    const defaultSl = isIndex ? 50 : (sym === 'USDMXN' ? 500 : 20);
    setSlDistance(defaultSl);

    // Preserve user's current risk % and balance when switching pairs
    calculateFromRiskPercent(riskPercent, defaultSl, balance);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [instrument]);

  // --- CALCULATION ENGINES ---

  const getValuePerUnit = () => {
    const { symbol, type, contractSize, pipSize } = instrument;

    let rawValue = contractSize * pipSize;

    const rates: Record<string, number> = {
        USDJPY: 152.00,
        USDCHF: 0.88,
        GBPUSD: 1.26,
        EURUSD: 1.05,
        USDMXN: 20.35
    };

    if (type === 'FOREX') {
        if (symbol.endsWith('USD')) return rawValue;
        if (symbol.endsWith('JPY')) return rawValue / rates.USDJPY;
        if (symbol.endsWith('CHF')) return rawValue / rates.USDCHF;
        if (symbol.endsWith('GBP')) return rawValue * rates.GBPUSD;
        if (symbol.endsWith('MXN')) return rawValue / rates.USDMXN;
        return rawValue; 
    }

    if (type === 'INDEX') {
        if (['NAS100', 'US30', 'SPX500'].includes(symbol)) return rawValue;
        if (symbol === 'UK100') return rawValue * rates.GBPUSD;
        if (symbol === 'FRA40') return rawValue * rates.EURUSD;
        if (symbol === 'JP225') return rawValue / rates.USDJPY;
        return rawValue;
    }

    return rawValue;
  };

  // 1. User types Risk %
  const calculateFromRiskPercent = (pct: number, dist: number, bal: number) => {
      const risk$ = bal * (pct / 100);
      setRiskPercent(pct);
      setRiskAmount(risk$);

      if (dist > 0) {
          const valPerUnit = getValuePerUnit();
          const lots = risk$ / (dist * valPerUnit);
          setLotSize(Number(lots.toFixed(2)));
      } else {
          setLotSize(0);
      }
  };

  // 2. User types Risk $
  const calculateFromRiskAmount = (amt: number, dist: number, bal: number) => {
      setRiskAmount(amt);
      setRiskPercent(Number(((amt / bal) * 100).toFixed(2)));

      if (dist > 0) {
          const valPerUnit = getValuePerUnit();
          const lots = amt / (dist * valPerUnit);
          setLotSize(Number(lots.toFixed(2)));
      }
  };

  // 3. User types Lot Size
  const calculateFromLots = (lots: number, dist: number, bal: number) => {
      setLotSize(lots);
      if (dist > 0) {
          const valPerUnit = getValuePerUnit();
          const risk$ = lots * dist * valPerUnit;
          setRiskAmount(Number(risk$.toFixed(2)));
          setRiskPercent(Number(((risk$ / bal) * 100).toFixed(2)));
      }
  };

  // --- HANDLERS ---

  const handleRiskPercentChange = (val: number) => {
      setCalcMode('FIXED_RISK');
      calculateFromRiskPercent(val, slDistance, balance);
  };

  const handleRiskAmountChange = (val: number) => {
      setCalcMode('FIXED_RISK');
      calculateFromRiskAmount(val, slDistance, balance);
  };

  const handleLotSizeChange = (val: number) => {
      setCalcMode('FIXED_LOTS');
      calculateFromLots(val, slDistance, balance);
  };

  const handleBalanceChange = (val: number) => {
      setBalance(val);
      calculateFromRiskPercent(riskPercent, slDistance, val);
  };

  const handleSlDistChange = (dist: number) => {
      setSlDistance(dist);
      if (entryPrice > 0) {
          const priceDist = dist * instrument.pipSize;
          const newPrice = direction === 'BUY' ? entryPrice - priceDist : entryPrice + priceDist;
          setSlPrice(Number(newPrice.toFixed(pricePrecision)));
      }
      if (calcMode === 'FIXED_RISK') {
          calculateFromRiskAmount(riskAmount, dist, balance);
      } else {
          calculateFromLots(lotSize, dist, balance);
      }
  };

  const handleSlPriceChange = (price: number) => {
      setSlPrice(price);
      if (entryPrice > 0) {
          const dist = Math.abs(entryPrice - price) / instrument.pipSize;
          const cleanDist = Number(dist.toFixed(1));
          setSlDistance(cleanDist);

          if (calcMode === 'FIXED_RISK') {
            calculateFromRiskAmount(riskAmount, cleanDist, balance);
          } else {
            calculateFromLots(lotSize, cleanDist, balance);
          }
      }
  };

  const handleEntryPriceChange = (price: number) => {
      setEntryPrice(price);
      if (price > 0 && slDistance > 0) {
          const slPriceDist = slDistance * instrument.pipSize;
          const newSlPrice = direction === 'BUY' ? price - slPriceDist : price + slPriceDist;
          setSlPrice(Number(newSlPrice.toFixed(pricePrecision)));
      }
      if (price > 0 && tpDistance > 0) {
          const tpPriceDist = tpDistance * instrument.pipSize;
          const newTpPrice = direction === 'BUY' ? price + tpPriceDist : price - tpPriceDist;
          setTpPrice(Number(newTpPrice.toFixed(pricePrecision)));
      }
  };

  const handleTpDistChange = (dist: number) => {
      setTpDistance(dist);
      if (entryPrice > 0) {
          const priceDist = dist * instrument.pipSize;
          const newPrice = direction === 'BUY' ? entryPrice + priceDist : entryPrice - priceDist;
          setTpPrice(Number(newPrice.toFixed(pricePrecision)));
      }
  };

  const handleTpPriceChange = (price: number) => {
      setTpPrice(price);
      if (entryPrice > 0) {
          const dist = Math.abs(entryPrice - price) / instrument.pipSize;
          setTpDistance(Number(dist.toFixed(1)));
      }
  };

  useEffect(() => {
    if (entryPrice > 0) {
        const slPriceDist = slDistance * instrument.pipSize;
        const tpPriceDist = tpDistance * instrument.pipSize;
        if (direction === 'BUY') {
            setSlPrice(Number((entryPrice - slPriceDist).toFixed(pricePrecision)));
            setTpPrice(Number((entryPrice + tpPriceDist).toFixed(pricePrecision)));
        } else {
            setSlPrice(Number((entryPrice + slPriceDist).toFixed(pricePrecision)));
            setTpPrice(Number((entryPrice - tpPriceDist).toFixed(pricePrecision)));
        }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [direction]);

  useEffect(() => {
      if (tpDistance > 0 && lotSize > 0) {
          const valPerUnit = getValuePerUnit();
          const reward = lotSize * tpDistance * valPerUnit;
          setRewardAmount(Number(reward.toFixed(2)));
          if (riskAmount > 0) {
            setRrRatio(Number((reward / riskAmount).toFixed(2)));
          }
      } else {
          setRewardAmount(0);
          setRrRatio(0);
      }
  }, [tpDistance, lotSize, riskAmount, instrument]);

  return (
    <div className="w-full max-w-5xl mx-auto p-4 md:p-6 animate-fade-in">

        {/* Header */}
        <div className="flex flex-col justify-between mb-6">
