      setSlDistance(dist);
      if (entryPrice > 0) {
          const priceDist = dist * instrument.pipSize;
          const newPrice = direction === 'BUY' ? entryPrice - priceDist : entryPrice + priceDist;
          setSlPrice(Number(newPrice.toFixed(pricePrecision)));
      }

      if (calcMode === 'FIXED_RISK') {
          calculateFromRiskAmount(riskAmount, dist, balance);
      } else {
          calculateFromLots(lotSize, dist, balance);
      }
