                                    className={`w-full bg-slate-950 border text-white px-4 py-3 rounded-xl font-mono text-lg font-bold outline-none transition-all shadow-inner ${calcMode === 'FIXED_LOTS' ? 'border-gold-500/50 shadow-[0_0_10px_rgba(212,175,55,0.05)]' : 'border-slate-700 focus:border-gold-500'}`}
