                    <div className="flex items-end justify-between px-1">
                        <label className="text-[10px] uppercase text-slate-500 font-bold tracking-wider">Entry Price</label>
                        <span className="text-[10px] text-gold-500 bg-gold-500/10 px-2 py-0.5 rounded">Current Market</span>
                    </div>

                    <div className="relative group">
                        <Crosshair className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-600" size={18} />
                        <input 
                            type="number" 
                            value={entryPrice || ''} 
                            onChange={(e) => handleEntryPriceChange(Number(e.target.value))}
                            className="w-full bg-slate-950 border border-slate-700 text-center text-2xl font-medium text-white py-4 rounded-xl focus:ring-1 focus:ring-gold-500 focus:border-gold-500 outline-none transition-all placeholder-slate-700"
                            placeholder="0.0000"
                        />
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <button
                            onClick={() => setDirection('SELL')}
                            className={`py-3 rounded-xl border transition-all duration-200 flex items-center justify-center gap-2 ${
                                direction === 'SELL' 
                                ? 'bg-rose-500/10 border-rose-500 text-rose-500 shadow-[0_0_15px_rgba(244,63,94,0.15)]' 
                                : 'bg-slate-950 border-slate-800 text-slate-500 hover:bg-slate-800 hover:border-slate-700'
                            }`}
                        >
                            <ArrowDownCircle size={18} />
                            <span className="font-bold tracking-wide">SELL</span>
                        </button>
                        <button
                            onClick={() => setDirection('BUY')}
                            className={`py-3 rounded-xl border transition-all duration-200 flex items-center justify-center gap-2 ${
                                direction === 'BUY' 
                                ? 'bg-emerald-500/10 border-emerald-500 text-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.15)]' 
                                : 'bg-slate-950 border-slate-800 text-slate-500 hover:bg-slate-800 hover:border-slate-700'
                            }`}
                        >
                            <ArrowUpCircle size={18} />
                            <span className="font-bold tracking-wide">BUY</span>
                        </button>
                    </div>
                </div>

                {/* --- SL / TP --- */}
                <div className="grid grid-cols-2 gap-4">
                    {/* STOP LOSS */}
                    <div className={`space-y-3 p-4 rounded-xl border transition-all ${slEnabled ? 'bg-slate-900 border-rose-500/30' : 'bg-slate-900 border-slate-800 opacity-50'}`}>
                        <div 
                            className="flex items-center gap-2 cursor-pointer group mb-2"
                            onClick={() => setSlEnabled(!slEnabled)}
                        >
                            {slEnabled ? <CheckSquare size={16} className="text-rose-500" /> : <Square size={16} className="text-slate-600" />}
                            <span className={`text-xs font-bold uppercase ${slEnabled ? 'text-rose-400' : 'text-slate-500'}`}>Stop Loss</span>
                        </div>

                        <div className="bg-slate-950 rounded-lg border border-slate-800 p-2 relative">
                            <span className="text-[9px] text-slate-500 absolute top-1 left-2 uppercase">Price</span>
                            <input 
                                type="number"
                                disabled={!slEnabled}
                                value={slPrice || ''}
                                onChange={(e) => handleSlPriceChange(Number(e.target.value))}
                                className="w-full bg-transparent text-right text-white font-medium outline-none pt-3 pb-0 text-sm"
                                placeholder="0.0000"
                            />
                        </div>
                        <div className="bg-slate-950 rounded-lg border border-slate-800 p-2 relative">
                            <span className="text-[9px] text-slate-500 absolute top-1 left-2 uppercase">{unitLabel}</span>
                            <input 
                                type="number"
                                disabled={!slEnabled}
                                value={slDistance || ''}
                                onChange={(e) => handleSlDistChange(Number(e.target.value))}
                                className="w-full bg-transparent text-right text-rose-300 font-medium outline-none pt-3 pb-0 text-sm"
                                placeholder="0"
                            />
                        </div>
                    </div>

                    {/* TAKE PROFIT */}
                    <div className={`space-y-3 p-4 rounded-xl border transition-all ${tpEnabled ? 'bg-slate-900 border-emerald-500/30' : 'bg-slate-900 border-slate-800 opacity-50'}`}>
                        <div 
                            className="flex items-center gap-2 cursor-pointer group mb-2"
                            onClick={() => setTpEnabled(!tpEnabled)}
                        >
                            {tpEnabled ? <CheckSquare size={16} className="text-emerald-500" /> : <Square size={16} className="text-slate-600" />}
                            <span className={`text-xs font-bold uppercase ${tpEnabled ? 'text-emerald-400' : 'text-slate-500'}`}>Take Profit</span>
                        </div>

                        <div className="bg-slate-950 rounded-lg border border-slate-800 p-2 relative">
                            <span className="text-[9px] text-slate-500 absolute top-1 left-2 uppercase">Price</span>
                            <input 
                                type="number"
                                disabled={!tpEnabled}
                                value={tpPrice || ''}
                                onChange={(e) => handleTpPriceChange(Number(e.target.value))}
                                className="w-full bg-transparent text-right text-white font-medium outline-none pt-3 pb-0 text-sm"
                                placeholder="0.0000"
                            />
                        </div>
                        <div className="bg-slate-950 rounded-lg border border-slate-800 p-2 relative">
                            <span className="text-[9px] text-slate-500 absolute top-1 left-2 uppercase">{unitLabel}</span>
                            <input 
                                type="number"
                                disabled={!tpEnabled}
                                value={tpDistance || ''}
                                onChange={(e) => handleTpDistChange(Number(e.target.value))}
                                className="w-full bg-transparent text-right text-emerald-300 font-medium outline-none pt-3 pb-0 text-sm"
                                placeholder="0"
                            />
                        </div>
                    </div>
                </div>
            </div>

            {/* --- RIGHT COLUMN: RESULTS PANEL (Cols 8-12) --- */}
            <div className="lg:col-span-5 flex flex-col h-full">
                <div className="bg-gradient-to-br from-slate-900 to-slate-950 rounded-3xl p-8 border border-slate-800 shadow-2xl relative overflow-hidden flex-1 flex flex-col">
                    {/* Decor */}
                    <div className="absolute -top-20 -right-20 w-64 h-64 bg-gold-500/5 rounded-full blur-3xl pointer-events-none"></div>

                    <div className="relative z-10 mb-auto">
                        <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mb-4">Position Overview</p>

                        {/* BIG LOTS */}
                        <div className="mb-8">
                             <div className="flex items-baseline gap-1">
                                <span className="text-6xl md:text-7xl font-serif text-white">{lotSize}</span>
                                <span className="text-gold-500 font-bold">Lots</span>
                             </div>
                             {calcMode === 'FIXED_RISK' ? (
                                <p className="text-xs text-slate-500 mt-2">Calculated based on your risk tolerance.</p>
                             ) : (
                                <p className="text-xs text-slate-500 mt-2">Manual lot size selected.</p>
                             )}
                        </div>
                    </div>

                    <div className="relative z-10 space-y-4">
                        {/* Risk Row */}
                        <div className="flex items-center justify-between p-4 bg-rose-500/5 border border-rose-500/10 rounded-xl">
                            <div className="flex items-center gap-3">
                                <div className="p-2 bg-rose-500/10 rounded-lg text-rose-500"><DollarSign size={18} /></div>
                                <div>
                                    <p className="text-[10px] uppercase text-rose-400 font-bold">Total Risk</p>
                                    <p className="text-white font-mono text-sm">Amount at stake</p>
                                </div>
                            </div>
                            <div className="text-right">
                                <p className="text-xl font-bold text-rose-500">-${riskAmount.toFixed(2)}</p>
                                <p className="text-xs text-rose-400/70">{riskPercent.toFixed(2)}%</p>
                            </div>
                        </div>

                        {/* Reward Row */}
                        <div className="flex items-center justify-between p-4 bg-emerald-500/5 border border-emerald-500/10 rounded-xl">
                            <div className="flex items-center gap-3">
                                <div className="p-2 bg-emerald-500/10 rounded-lg text-emerald-500"><Target size={18} /></div>
                                <div>
                                    <p className="text-[10px] uppercase text-emerald-400 font-bold">Target Profit</p>
                                    <p className="text-white font-mono text-sm">Potential Gain</p>
                                </div>
                            </div>
                            <div className="text-right">
                                <p className={`text-xl font-bold ${rewardAmount > 0 ? 'text-emerald-500' : 'text-slate-600'}`}>
                                    {rewardAmount > 0 ? `+$${rewardAmount.toFixed(2)}` : '--'}
                                </p>
                                <p className="text-xs text-emerald-400/70">
                                    {rrRatio > 0 ? `1:${rrRatio} R:R` : ''}
                                </p>
                            </div>
                        </div>
                    </div>

                    <div className="mt-8 pt-6 border-t border-slate-800/50">
                        <button 
                            onClick={openLogModal}
                            className={`w-full py-4 rounded-xl font-bold uppercase tracking-wider transition-all shadow-lg ${
                            direction === 'BUY' 
                            ? 'bg-emerald-600 hover:bg-emerald-500 text-white shadow-emerald-900/20' 
                            : 'bg-rose-600 hover:bg-rose-500 text-white shadow-rose-900/20'
                        }`}>
                            Execute {direction} Trade
                        </button>
                    </div>
                </div>
            </div>

        </div>

        {/* --- LOG TRADE MODAL --- */}
        {showLogModal && (
            <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
                <div className="bg-slate-900 rounded-2xl border border-slate-700 w-full max-w-lg p-6 shadow-2xl animate-fade-in">
                    <h3 className="text-xl font-serif text-white mb-6">Log New Trade</h3>

                    <div className="grid grid-cols-2 gap-4 mb-4">
                        <div>
                            <label className="text-xs text-slate-400 uppercase">Date</label>
                            <input 
                                type="date" 
                                className="w-full bg-slate-950 border border-slate-700 rounded p-2 text-white" 
                                value={tradeToLog.date} 
                                onChange={e => setTradeToLog({...tradeToLog, date: e.target.value})} 
                            />
                        </div>
                        <div>
                            <label className="text-xs text-slate-400 uppercase">Pair</label>
                            <div className="relative">
                                <select 
                                    className="w-full bg-slate-950 border border-slate-700 rounded p-2 text-white appearance-none"
                                    value={tradeToLog.pair} 
                                    onChange={e => setTradeToLog({...tradeToLog, pair: e.target.value})}
                                >
                                    {INSTRUMENTS.map(i => <option key={i.symbol} value={i.symbol}>{i.symbol}</option>)}
                                </select>
                                <ChevronDown size={14} className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" />
                            </div>
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4 mb-4">
                        <div>
                            <label className="text-xs text-slate-400 uppercase">Type</label>
                            <div className="flex bg-slate-950 rounded p-1 border border-slate-700">
                                <button onClick={() => setTradeToLog({...tradeToLog, type: 'BUY'})} className={`flex-1 text-sm py-1 rounded ${tradeToLog.type === 'BUY' ? 'bg-emerald-600 text-white' : 'text-slate-400'}`}>Buy</button>
                                <button onClick={() => setTradeToLog({...tradeToLog, type: 'SELL'})} className={`flex-1 text-sm py-1 rounded ${tradeToLog.type === 'SELL' ? 'bg-rose-600 text-white' : 'text-slate-400'}`}>Sell</button>
                            </div>
                        </div>
                        <div>
                            <label className="text-xs text-slate-400 uppercase">Lots</label>
                            <input 
                                type="number" step="0.01" 
                                className="w-full bg-slate-950 border border-slate-700 rounded p-2 text-white" 
                                value={tradeToLog.lotSize} 
                                onChange={e => setTradeToLog({...tradeToLog, lotSize: parseFloat(e.target.value)})} 
                            />
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4 mb-4">
                        <div>
                            <label className="text-xs text-slate-400 uppercase">Result (P/L $)</label>
                            <input 
                                type="number" step="0.01" 
                                className="w-full bg-slate-950 border border-slate-700 rounded p-2 text-white font-bold" 
                                placeholder="0.00"
                                value={tradeToLog.pnl} 
                                onChange={e => setTradeToLog({...tradeToLog, pnl: parseFloat(e.target.value)})} 
                            />
                        </div>
                        <div>
                            <label className="text-xs text-slate-400 uppercase">Status</label>
                            <select 
                                className="w-full bg-slate-950 border border-slate-700 rounded p-2 text-white"
                                value={tradeToLog.status} 
                                onChange={e => setTradeToLog({...tradeToLog, status: e.target.value as any})}
                            >
                                <option value="PENDING">Pending</option>
                                <option value="WIN">Win</option>
                                <option value="LOSS">Loss</option>
                                <option value="BREAKEVEN">Breakeven</option>
                            </select>
                        </div>
                    </div>

                    <div className="mb-6">
                        <label className="text-xs text-slate-400 uppercase">Setup / Strategy</label>
                        <input 
                            type="text" 
                            className="w-full bg-slate-950 border border-slate-700 rounded p-2 text-white" 
                            placeholder="e.g. Trendline bounce, Gold Cross..."
                            value={tradeToLog.setup} 
                            onChange={e => setTradeToLog({...tradeToLog, setup: e.target.value})} 
                        />
                    </div>

                    <div className="flex gap-3">
                        <button onClick={() => setShowLogModal(false)} className="flex-1 py-3 text-slate-400 hover:text-white transition-colors">Cancel</button>
                        <button onClick={saveLogTrade} className="flex-1 py-3 bg-gold-600 hover:bg-gold-500 text-slate-900 font-bold rounded-lg transition-colors">Save Trade</button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

export default Calculator;
